<script lang="ts">
	import { createEventDispatcher } from 'svelte'; import type { RecordValue } from '$lib/api';
	export let settings: RecordValue = {}; export let compact = false;
	const dispatch = createEventDispatcher<{ change: { settings: RecordValue } }>();
	const estimators = [['logistic_regression','Logistic regression'],['linear_svm','Linear SVM'],['gradient_boosting','Gradient boosted trees'],['shallow_mlp','Shallow MLP']] as const;
	function update(key:string, value:unknown) { settings={...settings,[key]:value}; dispatch('change',{settings}); }
	function option(key:string,value:unknown) { update('classifier_options',{...((settings.classifier_options as RecordValue) ?? {}),[key]:value}); }
	function number(key:string,event:Event) { const n=Number((event.currentTarget as HTMLInputElement).value); option(key,Number.isFinite(n)?n:0); }
	function settingNumber(key:string,event:Event) { const n=Number((event.currentTarget as HTMLInputElement).value); update(key,Number.isFinite(n)?n:0); }
	function setEstimator(event:Event) { settings={...settings,estimator:(event.currentTarget as HTMLSelectElement).value,classifier_options:{}}; dispatch('change',{settings}); }
	function layers() { const value=opts.hidden_layer_sizes; return Array.isArray(value)?value.map(Number):[100]; }
	function setLayer(index:number,event:Event) { const next=layers(); next[index]=Number((event.currentTarget as HTMLInputElement).value); option('hidden_layer_sizes',next); }
	function setLayerCount(event:Event) { option('hidden_layer_sizes',Number((event.currentTarget as HTMLSelectElement).value)===2?[layers()[0]??100,layers()[1]??64]:[layers()[0]??100]); }
	$: opts=(settings.classifier_options as RecordValue) ?? {}; $: enabled=settings.enabled===true; $: estimator=String(settings.estimator??'logistic_regression');
</script>

<div class:compact class="posthoc-controls"><label class="toggle"><input type="checkbox" checked={enabled} on:change={(e)=>update('enabled',e.currentTarget.checked)} /><span>Enable post-hoc classifier</span></label>
{#if enabled}<div class="control-grid"><label><span>Representation</span><select value={String(settings.representation??'fused_embedding')} on:change={(e)=>update('representation',e.currentTarget.value)}><option value="fused_embedding">Fused embedding</option></select></label><label><span>Classifier</span><select value={estimator} on:change={setEstimator}>{#each estimators as [value,label]}<option {value}>{label}</option>{/each}</select></label><label><span>Scaling</span><select value={String(settings.scaling??'standard')} on:change={(e)=>update('scaling',e.currentTarget.value)}><option value="standard">Standard scaler</option><option value="robust">Robust scaler</option><option value="none">None</option></select></label><label><span>Random seed</span><input type="number" min="0" value={Number(settings.seed??42)} on:change={(e)=>settingNumber('seed',e)} /></label>{#if estimator==='linear_svm'}<label><span>Calibration folds</span><input type="number" min="2" max="10" value={Number(settings.calibration_folds??3)} on:change={(e)=>settingNumber('calibration_folds',e)} /></label>{/if}<label class="toggle"><input type="checkbox" checked={settings.pca_enabled===true} on:change={(e)=>update('pca_enabled',e.currentTarget.checked)} /><span>Reduce dimensions with PCA</span></label>{#if settings.pca_enabled===true}<label><span>PCA output dimensions</span><input type="number" min="1" value={Number(settings.pca_components??32)} on:change={(e)=>settingNumber('pca_components',e)} /></label>{/if}<label class="toggle"><input type="checkbox" checked={settings.tune!==false} on:change={(e)=>update('tune',e.currentTarget.checked)} /><span>Tune bounded candidates (up to 3)</span></label></div>
<div class="control-grid estimator-options">{#if estimator==='logistic_regression'||estimator==='linear_svm'}<label><span>Regularization C</span><input type="number" min="0.0001" step="0.1" value={Number(opts.C??1)} on:change={(e)=>number('C',e)} /></label><label><span>Class weights</span><select value={opts.class_weight==='balanced'?'balanced':'none'} on:change={(e)=>option('class_weight',e.currentTarget.value==='balanced'?'balanced':null)}><option value="none">None</option><option value="balanced">Balanced</option></select></label>{/if}{#if estimator==='logistic_regression'||estimator==='linear_svm'}<label><span>Iteration limit</span><input type="number" min="1" value={Number(opts.max_iter??1000)} on:change={(e)=>number('max_iter',e)} /></label>{/if}{#if estimator==='linear_svm'}<label><span>Convergence tolerance</span><input type="number" min="0.000001" step="0.0001" value={Number(opts.tol??0.0001)} on:change={(e)=>number('tol',e)} /></label>{/if}{#if estimator==='gradient_boosting'}<label><span>Trees</span><input type="number" min="10" value={Number(opts.n_estimators??100)} on:change={(e)=>number('n_estimators',e)} /></label><label><span>Learning rate</span><input type="number" min="0.001" step="0.01" value={Number(opts.learning_rate??0.1)} on:change={(e)=>number('learning_rate',e)} /></label><label><span>Tree depth</span><input type="number" min="1" value={Number(opts.max_depth??3)} on:change={(e)=>number('max_depth',e)} /></label><label><span>Minimum leaf size</span><input type="number" min="1" value={Number(opts.min_samples_leaf??1)} on:change={(e)=>number('min_samples_leaf',e)} /></label><label><span>Subsample</span><input type="number" min="0.01" max="1" step="0.05" value={Number(opts.subsample??1)} on:change={(e)=>number('subsample',e)} /></label>{/if}{#if estimator==='shallow_mlp'}<label><span>Hidden layers</span><select value={String(layers().length)} on:change={setLayerCount}><option value="1">One</option><option value="2">Two</option></select></label><label><span>First layer width</span><input type="number" min="1" value={layers()[0]??100} on:change={(e)=>setLayer(0,e)} /></label>{#if layers().length===2}<label><span>Second layer width</span><input type="number" min="1" value={layers()[1]??64} on:change={(e)=>setLayer(1,e)} /></label>{/if}<label><span>Activation</span><select value={String(opts.activation??'relu')} on:change={(e)=>option('activation',e.currentTarget.value)}><option value="relu">ReLU</option><option value="tanh">Tanh</option><option value="logistic">Logistic</option><option value="identity">Identity</option></select></label><label><span>L2 regularization</span><input type="number" min="0" step="0.0001" value={Number(opts.alpha??0.0001)} on:change={(e)=>number('alpha',e)} /></label><label><span>Learning rate</span><input type="number" min="0.00001" step="0.0001" value={Number(opts.learning_rate_init??0.001)} on:change={(e)=>number('learning_rate_init',e)} /></label><label><span>Batch size</span><input type="number" min="1" value={Number(opts.batch_size??200)} on:change={(e)=>number('batch_size',e)} /></label><label><span>Max epochs</span><input type="number" min="10" value={Number(opts.max_iter??300)} on:change={(e)=>number('max_iter',e)} /></label><label class="toggle"><input type="checkbox" checked={opts.early_stopping===true} on:change={(e)=>option('early_stopping',e.currentTarget.checked)} /><span>Early stopping</span></label>{#if opts.early_stopping===true}<label><span>Validation fraction</span><input type="number" min="0.01" max="0.99" step="0.05" value={Number(opts.validation_fraction??0.1)} on:change={(e)=>number('validation_fraction',e)} /></label>{/if}{/if}</div>{/if}</div>

<style>.posthoc-controls{margin-top:.65rem}.control-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:.65rem;align-items:end}.control-grid label{display:grid;gap:.25rem}.control-grid span{font-size:.7rem;font-weight:700;color:var(--muted);text-transform:uppercase}.control-grid .toggle{display:flex;align-items:center;gap:.45rem;min-height:2.4rem}.control-grid .toggle input{width:auto;min-height:auto}.control-grid .toggle span{text-transform:none;color:var(--ink);font-size:.78rem}.estimator-options{margin-top:.7rem;padding-top:.7rem;border-top:1px solid var(--line)}.compact{margin-top:0}</style>
